const KEY='pantry-v1';
const uid=()=>crypto.randomUUID();
const initial=()=>({checked:'',categories:[{id:uid(),name:'Fridge',items:[{id:uid(),name:'Milk',status:'low'},{id:uid(),name:'Butter',status:'have'},{id:uid(),name:'Eggs',status:'have'},{id:uid(),name:'Yogurt',status:'empty'}]},{id:uid(),name:'Pantry',items:[{id:uid(),name:'Cornflakes',status:'low'},{id:uid(),name:'Pasta',status:'have'},{id:uid(),name:'Rice',status:'have'},{id:uid(),name:'Olive oil',status:'have'}]}]});
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved&&Array.isArray(saved.categories)?saved:initial()}catch{state=initial()}
let filter='all',editing=false,editTarget=null,timer;
const $=s=>document.querySelector(s),el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Storage is unavailable. Changes will last only this visit.')}render()}
function button(text,cls,action,label){const b=el('button',cls,text);b.type='button';b.onclick=action;if(label)b.setAttribute('aria-label',label);return b}
function reorder(array,index,delta){const next=index+delta;if(next<0||next>=array.length)return;[array[index],array[next]]=[array[next],array[index]];save()}
function arrows(array,index,name){const wrap=el('div','order');for(const [d,s] of [[-1,'↑'],[1,'↓']]){const b=button(s,'',()=>{reorder(array,index,d);toast(name+' moved '+(d<0?'up':'down'))},'Move '+name+(d<0?' up':' down'));b.disabled=index+d<0||index+d>=array.length;wrap.append(b)}return wrap}
const statusNames={empty:['−','Empty'],low:['◔','Buy soon'],have:['✓','In stock']};
function render(){const items=state.categories.flatMap(c=>c.items);$('#all-count').textContent=items.length;$('#buy-count').textContent=items.filter(i=>i.status!=='have').length;$('#checked-date').value=state.checked||'';$('#never').hidden=!!state.checked;$('#organize').classList.toggle('selected',editing);$('#organize').setAttribute('aria-pressed',editing);$('#organize span').textContent=editing?'Done':'Rearrange';$('.organize-help').hidden=!editing;const root=$('#categories');root.replaceChildren();root.classList.toggle('editing',editing);document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)});
state.categories.forEach((cat,ci)=>{const shown=cat.items.filter(i=>filter==='all'||i.status!=='have');if(filter==='buy'&&!shown.length&&!editing)return;const card=el('section','category');const head=el('div','category-head');const emoji=/fridge/i.test(cat.name)?'❄':/freezer/i.test(cat.name)?'❆':'▤';head.append(el('span','category-emoji',emoji),button(cat.name,'category-name',()=>openEditor('category',cat), 'Edit '+cat.name),el('span','item-count',cat.items.length+' items'));if(editing)head.append(arrows(state.categories,ci,cat.name));head.append(button('···','quiet',()=>openEditor('category',cat),'Edit '+cat.name));card.append(head);
shown.forEach(item=>{const row=el('div','row');if(editing)row.append(arrows(cat.items,cat.items.indexOf(item),item.name));row.append(button(item.name,'item-name',()=>openEditor('item',cat,item),'Edit '+item.name));const statuses=el('div','status');statuses.setAttribute('role','group');statuses.setAttribute('aria-label',item.name+' stock status');Object.entries(statusNames).forEach(([key,[symbol,name]])=>{const b=button('',''+key+(item.status===key?' active':''),()=>{item.status=key;save()},item.name+': '+name);b.setAttribute('aria-pressed',item.status===key);b.append(el('span','',symbol),document.createTextNode(name));statuses.append(b)});row.append(statuses);
if(editing){const select=el('select','move-select');select.setAttribute('aria-label','Move '+item.name+' to category');state.categories.forEach(c=>{const option=el('option','',c.name);option.value=c.id;option.selected=c.id===cat.id;select.append(option)});select.onchange=()=>{const target=state.categories.find(c=>c.id===select.value);cat.items=cat.items.filter(i=>i.id!==item.id);target.items.push(item);save();toast(item.name+' moved to '+target.name)};row.append(select)}card.append(row)});
if(!shown.length)card.append(el('p','empty-message',filter==='buy'?'All stocked up.':'A fresh shelf. Add your first item.'));card.append(button('＋ Add an item','add-item',()=>openEditor('item',cat)));root.append(card)});
if(!root.children.length)root.append(el('p','empty-message',filter==='buy'?'All stocked up. Nothing to buy.':'Start with a category, like Fridge or Pantry.'));
}
function openEditor(kind,cat=null,item=null){editTarget={kind,cat,item};const existing=kind==='category'?cat:item;$('#dialog-title').textContent=(existing?'Edit ':'Add ')+(kind==='category'?'a category':'an item');$('#name').value=existing?.name||'';$('#name').placeholder=kind==='category'?'e.g. Freezer':'e.g. Oat milk';$('#delete').hidden=!existing;$('#editor').showModal();$('#name').focus()}
$('#edit-form').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();if(!name){$('#name').setCustomValidity('Enter a name.');$('#name').reportValidity();return}const {kind,cat,item}=editTarget;if(kind==='category'){if(cat)cat.name=name;else state.categories.push({id:uid(),name,items:[]})}else if(item)item.name=name;else cat.items.push({id:uid(),name,status:'have'});$('#editor').close();save()};
$('#name').oninput=()=>$('#name').setCustomValidity('');$('#close-dialog').onclick=()=>$('#editor').close();$('#delete').onclick=()=>{const{kind,cat,item}=editTarget;const name=kind==='category'?cat.name:item.name;if(!confirm('Delete '+name+(kind==='category'&&cat.items.length?' and its '+cat.items.length+' items':'')+'?'))return;if(kind==='category')state.categories=state.categories.filter(c=>c.id!==cat.id);else cat.items=cat.items.filter(i=>i.id!==item.id);$('#editor').close();save();toast(name+' deleted')};
$('#add-category').onclick=()=>openEditor('category');$('#organize').onclick=()=>{editing=!editing;render()};document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});
$('#check-today').onclick=()=>{const d=new Date();state.checked=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');save();toast('Pantry checked. You’re up to date.')};$('#checked-date').onchange=e=>{state.checked=e.target.value;save()};window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=JSON.parse(e.newValue);render()}catch{}}});render();
